import math
from typing import Sequence

def rho(s: float, x: float) -> float:
    return math.exp(-math.pi * x * x / (s * s))

def discrete_gaussian(s: float, pts: Sequence[float], x: float) -> float:
    return rho(s, x) / sum(rho(s, y) for y in pts)

s = 2.5
pts = [float(k) for k in range(-6, 7)]
masses = [discrete_gaussian(s, pts, x) for x in pts]
print('sum =', sum(masses))
assert math.isclose(sum(masses), 1.0)
assert all(0.0 <= m <= 1.0 for m in masses)
print('peak p =', max(masses))

import math
from typing import Callable

p = 7
def f(x: int) -> float:
    return math.exp(-math.pi * x * x / 4.0)

for a in range(1, p):
    for b in range(p):
        g: Callable[[int], int] = lambda x, a=a, b=b: (a * x + b) % p
        assert sorted(g(x) for x in range(p)) == list(range(p))
        lhs = sum(f(g(x)) for x in range(p))
        rhs = sum(f(x) for x in range(p))
        assert math.isclose(lhs, rhs)
print('all affine maps over Z_7 are bijections and sum-invariant')

