function SampleDiscreteGaussian(s, P):
    for x in P: w[x] <- exp(-pi * x^2 / s^2)
    Z <- sum_x w[x]                # Z > 0 since P nonempty
    build cumulative array C over P with C[k] = (w[P_0]+...+w[P_k])/Z
    u <- Uniform(0,1)
    return smallest P_k with C[k] >= u   # inverse-CDF, binary search

